from collections import defaultdict
H=len(g); W=13
segs=[]
# find maximal diagonal runs of 1s
for dr,dc in [(1,1),(1,-1)]:
    used=set()
    for r in range(H):
        for c in range(W):
            if g[r][c]==1 and (r,c) not in used:
                # start of run: previous not 1
                pr,pc=r-dr,c-dc
                if 0<=pr<H and 0<=pc<W and g[pr][pc]==1: continue
                run=[]; rr,cc=r,c
                while 0<=rr<H and 0<=cc<W and g[rr][cc]==1:
                    run.append((rr,cc)); used.add((rr,cc)); rr+=dr; cc+=dc
                segs.append((dr,dc,run[0],run[-1],len(run)))
for s in segs: print(s)
print('2 cells:',[(r,c) for r in range(H) for c in range(W) if g[r][c]==2])

def solve(inp):
    c0 = inp.index(2)
    W = len(inp); H = W  # demo: H = W = 2*c0+1
    out = [[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if 0 <= r <= c0 and (c == c0 - r or c == c0 + r):
                out[r][c] = 2
            elif (r - c) % 4 == (-c0) % 4 and r - c > -c0 and r + c > c0:
                out[r][c] = 1
    return out

# verify on demo
inp = [0]*13; inp[6] = 2
pred = solve(inp)
print("demo match:", pred == g)
for r in pred: print(''.join(str(v) for v in r))
